import type { ButtonGroupProps } from "./button-group.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

const componentName = "ButtonGroup";

export const ButtonGroupClasses = {
  root: "exp-textura_button-group",
};

const generateStyles = (props: ButtonGroupProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ButtonGroupProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "flex",
    flexWrap: "inherit",
    flexDirection: "row",
    gap: theme.toRem(theme.spacing[8]),

    ...styleSlots?.root,
  };
};

const excludedDOMProps = getExcludedDOMProps();

export const StyledButtonGroup = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<ButtonGroupProps>((props) => generateStyles(props));
